function parse({ query }) {
  const error = "INVALID action_input. Supply ?url=ENCODED_URL&method=full or simplified";
  if (typeof query !== "string")
    return { ok: false, error, url: "", method: "full", maxlimit: 70000 };
  let data = {};
  try {
    for (const p of query.slice(query.indexOf("?") + 1).split("&")) {
      const i = p.indexOf("=");
      if (i >= 0) data[decodeURIComponent(p.slice(0, i))] = decodeURIComponent(p.slice(i + 1));
    }
  } catch {
    return { ok: false, error, url: "", method: "full", maxlimit: 70000 };
  }
  const url = data.url ?? "",
    method = data.method ?? "full",
    maxlimit = data.maxlimit === undefined ? 70000 : Number(data.maxlimit);
  if (
    !/^https?:\/\//i.test(url) ||
    !["full", "simplified"].includes(method) ||
    !Number.isFinite(maxlimit) ||
    maxlimit < 1
  )
    return { ok: false, error, url: "", method: "full", maxlimit: 70000 };
  return { ok: true, error: "", url, method, maxlimit };
}

return { json: parse({ query: $json.query }) };

function format({ body, method, maxlimit }) {
  if (!body || body.success !== true || typeof body.data?.markdown !== "string")
    return {
      page_content: "ERROR: " + String(body?.error ?? "Page content unavailable"),
      page_length: 0,
    };
  let text = body.data.markdown;
  if (method === "simplified")
    text = text
      .replace(/!\[([^\]]*)\]\([^)]*\)/g, "![$1](NOIMG)")
      .replace(/(?<!!)\[([^\]]*)\]\([^)]*\)/g, "[$1](NOURL)");
  return {
    page_content: text.length < maxlimit ? text : "ERROR: PAGE CONTENT TOO LONG",
    page_length: text.length,
  };
}

const q = $("Parse request").item.json;
return { json: format({ body: $json, method: q.method, maxlimit: q.maxlimit }) };
